def get_primitive_name(schema):
    """ Get a human-friendly name for the given primitive.

    :param schema: Schema
    :type schema: *
    :rtype: unicode
    """
    if schema.get('$ref'):
        return schema['$ref'].split('/')[-1]

    if schema.get('type') == 'array':
        return 'Array of {}'.format(get_primitive_name(schema['items']))

    if schema.get('type') == 'object':
        return 'Object'

    if schema.get('type') == 'string':
        return 'String'

    if schema.get('type') == 'number':
        return 'Number'

    if schema.get('type') == 'boolean':
        return 'Boolean'

    if schema.get('type') == 'null':
        return 'Null'

    if schema.get('enum'):
        return 'Enum of {}'.format(schema['enum'])

    if schema.get('allOf'):
        return 'Union of {}'.format(
            ', '.join(get_primitive_name(s) for s in schema['allOf'])
        )

    if schema.get('oneOf'):
        return 'Union of {}'.format(
            ', '.join(get_primitive_name(s) for s in schema['oneOf'])
        )

    if schema.get('anyOf'):
        return 'Union of {}'.format(
            ', '.join(get_primitive_name(s) for s in schema['anyOf'])
        )

    if schema.get('not'):
        return 'Not {}'.format(get_primitive_name(schema['not']))

    if schema.get('type') == 'integer':
        return 'Integer'

    if schema.get('type') == 'array':
        return 'Array'

    if schema.get('type') == 'object':
        return 'Object'

    if schema.get('type') == 'string':
        return 'String'

    if schema.get('type') == 'number':
        return 'Number'

    if schema.get('type') == 'boolean':
        return 'Boolean'

    if schema.get('type') == 'null':
        return 'Null'

    if schema.get('enum'):
        return 'Enum of {}'.

